# Convert dimensionless scale quantities before discarding their units.
if self.scale.unit is not None and self.scale.unit.is_equivalent(u.dimensionless_unscaled):
    scale = self.scale.quantity.to_value(u.dimensionless_unscaled)
else:
    scale = self.scale.value
# bolometric flux in the native units of the planck function
native_bolflux = (
    scale * const.sigma_sb * self.temperature ** 4 / np.pi
)
